WORD v_hardcopy(WORD handle)
{
    gem_vdi_packet_t packet = {.handle = handle, .function = rpc_v_hardcopy};
    int32_t result = 0;
    size_t used = 0;
    packet.args[0] = handle;
    (void)used;
    if (!gem_rpc_call(GEM_RPC_VDI_EXT, &packet, sizeof(packet), &result,
                      &packet, sizeof(packet)))
        return 0;
    used = 0;
    (void)used;
    return (WORD)result;
}

